class SavingsAccount extends BankAccount
{
    int balance = 15000;

    SavingsAccount()
    {
        System.out.println("Savings Account Created");
        super();
    }

    void display()
    {
        System.out.println("Savings Balance: " + super.balance);
        super.display;
